insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_97_v1'
from (values
('127.751.d.1.A',3,'In Law Enforcement II, a student reads a role-play partner''s folded arms, clenched jaw and pacing. The student is evaluating:','["body language and gestures", "tax forms", "radio codes", "badge numbers"]'::jsonb,0,'Nonverbal cues add meaning to words.','original'),
('127.751.d.1.A',4,'A suspect says ''I''m fine'' but trembles and avoids eye contact. The officer should treat the gestures as:','["a confession", "clues to weigh with other facts", "irrelevant noise", "proof of a crime"]'::jsonb,1,'Body language is a clue, not proof.','original'),
('127.751.d.1.B',3,'An advanced student calmly restates an upset neighbor''s complaint before offering options. This is:','["a use of force", "writing a ticket", "interpersonal communication skill", "avoiding the neighbor"]'::jsonb,2,'Restating shows understanding.','original'),
('127.751.d.1.B',4,'Which approach best builds rapport during a citizen contact?','["Speaking only in code", "Raising your voice at once", "Ignoring questions", "Using a respectful tone and listening before directing"]'::jsonb,3,'Respect and listening build cooperation.','original'),
('127.751.d.1.C',3,'At a mock burglary, a student jots times, addresses and quotes in a pocket notebook to use later in a report. This is:','["effective field note taking", "parking", "daydreaming", "filing a lawsuit"]'::jsonb,0,'Notes preserve details for reports.','original'),
('127.751.d.1.C',4,'Field notes are most useful when they are written:','["as opinions only", "at or near the time events happen, in clear facts", "in secret symbols", "a month later from memory"]'::jsonb,1,'Prompt, factual notes are most reliable.','original'),
('127.751.d.1.D',3,'A class designs a scenario in which two officers approach a parked car and arrest a driver with an outstanding warrant. This uses:','["budget planning", "classroom seating", "patrol tactics to effect an arrest", "traffic counts"]'::jsonb,2,'Scenarios rehearse arrest tactics.','original'),
('127.751.d.1.D',4,'A good patrol arrest scenario includes assigning roles such as contact officer and:','["spectator", "vendor", "lawyer", "cover officer"]'::jsonb,3,'Cover officer protects the contact officer.','original'),
('127.751.d.1.E',3,'A student matches ''detention facility'', ''dispatcher'' and ''bailiff'' to their meanings. This is learning:','["law, public safety, corrections and security terms", "music terms", "cooking words", "sports slang"]'::jsonb,0,'Correct vocabulary aids clear communication.','original'),
('127.751.d.1.E',4,'Which term names a person who keeps order in a courtroom?','["dispatcher", "bailiff", "jailer''s cook", "mechanic"]'::jsonb,1,'Bailiffs maintain courtroom security.','original'),
('127.751.d.2.A',3,'A cadet checks that a handheld radio''s battery is charged and the channel set before patrol. This supports:','["cooking", "print shop work", "use of mobile and handheld radio systems", "filing taxes"]'::jsonb,2,'Reliable radios need preparation.','original'),
('127.751.d.2.A',4,'Before leaving on patrol, an officer should test the radio so that:','["the siren is quieter", "fuel lasts longer", "the car is cleaner", "contact with dispatch is assured"]'::jsonb,3,'A radio check confirms communication.','original'),
('127.751.d.2.B',3,'Over a practice radio, a student spells a license plate as ''Adam, Baker, Charlie'' to prevent confusion. This is the:','["phonetic alphabet", "tax code", "Morse flag code", "shorthand grammar"]'::jsonb,0,'Phonetic words clarify letters.','original'),
('127.751.d.2.B',4,'Why do officers use the phonetic alphabet on the radio?','["It sounds friendly", "Letters like B and D sound alike over static", "It saves paper", "It is a tradition only"]'::jsonb,1,'Phonetics avoid mishearing.','original'),
('127.751.d.2.C',3,'A student runs a plate check through a patrol car''s laptop in a drill. This is using:','["a fax", "a typewriter", "mobile data computers for communication", "a pager"]'::jsonb,2,'MDCs send and receive data.','original'),
('127.751.d.2.C',4,'A key benefit of sending a records check by data terminal instead of voice is that it:','["is always faster than thought", "removes the need for dispatch", "needs no training", "reduces radio traffic and keeps information more private"]'::jsonb,3,'Data traffic frees the air.','original'),
('127.751.d.2.D',3,'A supervisor warns officers not to discuss sensitive details on open radio channels where scanners can listen. This evaluates:','["safety concerns with telecommunications equipment", "fuel cost", "fashion", "parking"]'::jsonb,0,'Open channels can be monitored.','original'),
('127.751.d.2.D',4,'Which practice improves safety when using a radio near a tense scene?','["Turning volume to maximum", "Keeping transmissions short and avoiding sensitive details", "Talking continuously", "Broadcasting suspect names"]'::jsonb,1,'Brief, careful traffic is safer.','original'),
('127.751.d.2.E',3,'A dispatcher must decide whether to send the next unit to a loud-music complaint or a person reporting a robbery in progress. This shows the need to:','["hang up", "answer in order only", "prioritize calls for service", "ignore calls"]'::jsonb,2,'Life-threatening calls come first.','original'),
('127.751.d.2.E',4,'Which call should normally receive the highest priority?','["a lost-property inquiry", "a barking dog report", "a parking complaint", "a crime in progress with a threat to life"]'::jsonb,3,'Threat to life is first.','original'),
('127.751.d.2.F',3,'During a hurricane, communications centers use special procedures to coordinate many agencies. These are:','["procedures for emergency communications incidents", "recreation plans", "daily routines only", "hiring steps"]'::jsonb,0,'Disasters require emergency communication plans.','original'),
('127.751.d.2.F',4,'In a major emergency, dispatch centers often keep communication working by:','["waiting for power only", "using backup channels and trained emergency procedures", "using no radios", "shutting down"]'::jsonb,1,'Backups sustain communications.','original'),
('127.751.d.3.A',3,'A student mapping a trial names the judge, prosecutor, defense attorney, bailiff and clerk. These make up the:','["audience", "press pool", "courtroom work group", "jury only"]'::jsonb,2,'Each role has a job.','original'),
('127.751.d.3.A',4,'In the courtroom work group, the prosecutor represents:','["the officer personally", "the defendant", "the jury", "the state"]'::jsonb,3,'Prosecutors act for the state.','original'),
('127.751.d.3.B',3,'The night before testifying, an officer rereads field notes, the report and the evidence log. This shows the importance of:','["reviewing notes, reports and evidence before testifying", "memorizing opinions", "guessing at details", "skipping prep"]'::jsonb,0,'Review keeps testimony accurate.','original'),
('127.751.d.3.B',4,'Reviewing a report before court helps an officer:','["skip the trial", "testify accurately and consistently", "change the facts", "avoid questions"]'::jsonb,1,'Consistency supports credibility.','original'),
('127.751.d.3.C',3,'In a mock trial, an officer identifies a recovered knife and explains how it was packaged and stored so it can be admitted. This is:','["hiding evidence", "discarding evidence", "properly introducing evidence for admission", "guessing"]'::jsonb,2,'Foundation shows the item is what it claims.','original'),
('127.751.d.3.C',4,'To admit an item of evidence, the officer must usually show:','["its price", "a verbal rumor", "its color preference", "what it is and the chain of custody"]'::jsonb,3,'Authenticity and custody matter.','original'),
('127.751.d.3.D',3,'A student practices answering a cross-examination question by listening, pausing and giving only a truthful, direct answer. This is:','["effective courtroom testimony", "guessing", "arguing with the lawyer", "volunteering opinions"]'::jsonb,0,'Direct, truthful answers are best.','original'),
('127.751.d.3.D',4,'When a lawyer asks a question an officer doesn''t understand, the officer should:','["argue", "ask for the question to be repeated or clarified", "walk out", "guess an answer"]'::jsonb,1,'Clarity prevents errors.','original'),
('127.751.d.3.E',3,'An officer arrives at court in a clean uniform, speaks respectfully and stays calm under tough questions. This shows:','["carelessness", "indifference", "professionalism in demeanor and appearance", "hostility"]'::jsonb,2,'Demeanor affects credibility.','original'),
('127.751.d.3.E',4,'Jurors often judge an officer''s credibility partly by the officer''s:','["car model", "favorite sport", "hometown", "professional demeanor and appearance"]'::jsonb,3,'Professional presentation builds trust.','original'),
('127.751.d.3.F',3,'Before a trial, the arresting officer meets the prosecutor to go over the facts and likely questions. This is a:','["pre-trial meeting with a prosecutor", "social visit", "vacation", "parking review"]'::jsonb,0,'Prep meetings clarify the case.','original'),
('127.751.d.3.F',4,'A pre-trial meeting helps the prosecutor by:','["avoiding the case", "identifying strengths, weaknesses and needed evidence", "replacing the judge", "hiding facts"]'::jsonb,1,'Meetings guide trial preparation.','original'),
('127.751.d.4.A',3,'An instructor compares open questions, reflective listening and calm tone as methods officers use to communicate. These are:','["courtroom seating", "traffic laws", "interpersonal communication techniques in law enforcement", "uniform rules"]'::jsonb,2,'Technique supports effective contact.','original'),
('127.751.d.4.A',4,'An officer says ''It sounds like you''re worried about your son.'' This technique is called:','["citation writing", "evidence tagging", "interrogation", "reflective listening"]'::jsonb,3,'Reflecting feelings shows understanding.','original'),
('127.751.d.4.B',3,'A person who stays silent and agrees but later sulks is acting:','["passive-aggressively", "openly", "assertively", "aggressively"]'::jsonb,0,'Passive-aggressive behavior is indirect.','original'),
('127.751.d.4.B',4,'Which statement is assertive rather than aggressive?','["''Whatever, I don''t care.''", "''I need you to step back so we can both stay safe.''", "''Back off or else!''", "''Do it, you fool!''"]'::jsonb,1,'Assertive is clear and respectful.','original'),
('127.751.d.4.C',3,'A rude, shouting caller won''t listen. A good officer lowers voice, stays courteous and sets clear limits. This is:','["ignoring the caller", "ending the call", "a strategy for dealing with difficult people", "matching the shouting"]'::jsonb,2,'Calm limits de-escalate.','original'),
('127.751.d.4.C',4,'A useful first step with an angry person is to:','["walk away", "argue back", "threaten arrest at once", "stay calm and let them vent briefly before directing"]'::jsonb,3,'Letting them vent often cools anger.','original'),
('127.751.d.4.D',3,'Fear, pain, intoxication, and feeling disrespected can all raise a person''s anger. These are:','["factors contributing to hostility", "budget lines", "clothing styles", "traffic laws"]'::jsonb,0,'Understanding causes aids response.','original'),
('127.751.d.4.D',4,'Knowing why a person is hostile helps an officer to:','["excuse crime", "choose a response that lowers tension", "skip reports", "raise tension"]'::jsonb,1,'Causes shape the best approach.','original'),
('127.751.d.5.A',3,'In a drill, a trained negotiator talks calmly to a barricaded subject to end the standoff without injury. This is:','["traffic control", "raiding", "crisis negotiation", "patrol parking"]'::jsonb,2,'Negotiation prioritizes safety.','original'),
('127.751.d.5.A',4,'The main goal of crisis negotiation is to:','["win an argument", "punish quickly", "avoid contact", "resolve the incident peacefully"]'::jsonb,3,'Peaceful resolution protects lives.','original'),
('127.751.d.5.B',3,'Students rotate as primary negotiator, coach and recorder in a simulation. This is serving as a:','["crisis negotiation team member", "witness only", "spectator", "bystander"]'::jsonb,0,'Teams share roles.','original'),
('127.751.d.5.B',4,'On a negotiation team, the coach mainly:','["directs traffic", "advises and supports the primary negotiator", "fills out ticketing", "kicks in doors"]'::jsonb,1,'Coaches support the negotiator.','original'),
('127.751.d.5.C',3,'A negotiator uses a steady voice, active listening and open-ended questions with an upset subject. These are:','["threats", "orders only", "effective communication techniques for crisis negotiation", "arguments"]'::jsonb,2,'Calm technique builds trust.','original'),
('127.751.d.5.C',4,'Which negotiator statement best builds trust?','["''You''re being foolish.''", "''You have no choice.''", "''Stop talking.''", "''Help me understand what''s happening for you.''"]'::jsonb,3,'Open invitations encourage talk.','original'),
('127.751.d.5.D',3,'While negotiating, a team confirms that hostages are alive and unharmed before agreeing to any demand. This is a:','["hostage safety consideration", "budget step", "media step", "paperwork step"]'::jsonb,0,'Verifying safety is critical.','original'),
('127.751.d.5.D',4,'Hostage safety is best protected when negotiators:','["make rash promises", "keep communication open and avoid actions that provoke harm", "raise the threat", "cut contact"]'::jsonb,1,'Steady contact lowers risk.','original'),
('127.751.d.5.E',3,'A negotiator weighs a subject''s request for a car against the risk to the public if he escapes. This differentiates:','["day from night", "wages from taxes", "public safety from individual rights", "food from drink"]'::jsonb,2,'Safety and rights must be balanced.','original'),
('127.751.d.5.E',4,'In a crisis, an officer may limit a person''s freedom only when:','["it is convenient", "the person is unpopular", "the officer is annoyed", "the law and the safety threat justify it"]'::jsonb,3,'Rights are limited only with legal reason.','original'),
('127.751.d.6.A',3,'An officer tells a theft victim about filing a protective order and seeking restitution. This demonstrates:','["advising crime victims of legal recourse", "closing a case", "writing a ticket", "ignoring victims"]'::jsonb,0,'Victims are informed of options.','original'),
('127.751.d.6.A',4,'Legal recourse for a crime victim may include:','["blaming the victim", "seeking restitution or compensation through the court", "dropping the report", "avoiding the courts"]'::jsonb,1,'Restitution is a recourse.','original'),
('127.751.d.6.B',3,'A student charts the steps from arrest to arraignment to trial for a suspect, victim and witness. This explains:','["school discipline", "tax filing", "step-by-step court procedures", "hiring"]'::jsonb,2,'Procedure guides participants.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_97_v1'
from (values
('127.751.d.6.B',4,'A witness receiving a subpoena is being told to:','["hire a lawyer", "pay a fine", "avoid the court", "appear and testify at a stated time"]'::jsonb,3,'A subpoena compels appearance.','original'),
('127.751.d.6.C',3,'An officer calls for an interpreter and speaks slowly while helping a hearing-impaired and a non-English-speaking person. This is:','["appropriate assistance to individuals with special needs", "ignoring them", "skipping reports", "delaying service"]'::jsonb,0,'Accommodation ensures access.','original'),
('127.751.d.6.C',4,'When assisting a person with a disability, an officer should:','["talk over them", "communicate respectfully and provide reasonable accommodation", "avoid contact", "rush"]'::jsonb,1,'Respect and accommodation matter.','original'),
('127.751.d.6.D',3,'An investigator reports to a scene involving a child victim and a victim of an elder-abuse report, following special steps. This is a:','["parking call", "traffic stop", "preliminary investigation of a special-victim case", "noise complaint"]'::jsonb,2,'Special victims need special procedures.','original'),
('127.751.d.6.D',4,'In a preliminary investigation, the officer first:','["writes final reports", "leaves", "closes the case", "ensures safety, aids the victim and secures the scene"]'::jsonb,3,'Safety and aid come first.','original'),
('127.751.d.6.E',3,'An officer plans to personally tell a family that their relative was killed in a crash, using a calm, clear and caring approach. This is a:','["death notification", "traffic stop", "warrant service", "patrol briefing"]'::jsonb,0,'Death notifications require care.','original'),
('127.751.d.6.E',4,'A good death notification is:','["done by a stranger by phone", "done in person, promptly and with compassion", "delayed for months", "sent by text"]'::jsonb,1,'In-person delivery shows respect.','original'),
('127.751.d.6.F',3,'A state law requires officers to give crime victims written information on their rights and services. This is a:','["suggestion", "hobby", "legal requirement of law enforcement toward victims", "rumor"]'::jsonb,2,'Officers must follow statutory duties.','original'),
('127.751.d.6.F',4,'Giving victims required notices and referrals is an example of:','["optional courtesy", "personal choice", "unrelated work", "meeting legal duties owed to crime victims"]'::jsonb,3,'Law requires victim notices.','original'),
('127.751.d.7.A',3,'An instructor explains that Texas law lets officers make an arrest without a warrant in certain family violence cases. This is a:','["technique to enforce domestic violence laws", "school rule", "traffic law", "civil trial"]'::jsonb,0,'Enforcement tools exist in law.','original'),
('127.751.d.7.A',4,'At a domestic violence call, enforcing the law includes:','["taking sides by sex", "separating the parties and determining the primary aggressor", "leaving at once", "ignoring the call"]'::jsonb,1,'Primary-aggressor analysis guides arrest.','original'),
('127.751.d.7.B',3,'In a role-play, two officers calm a shouting couple by separating them and speaking quietly. This is:','["escalating a fight", "ignoring a call", "defusing a simulated domestic violence incident", "writing tickets"]'::jsonb,2,'De-escalation lowers risk.','original'),
('127.751.d.7.B',4,'A key step in defusing a heated domestic dispute is to:','["shout orders", "leave weapons in reach", "take sides", "separate the people and keep a calm voice"]'::jsonb,3,'Separation and calm help.','original'),
('127.751.d.7.C',3,'After finding probable cause that an assault occurred in a home, an officer decides to arrest. This is:','["applying law in making an arrest", "a favor", "a trial", "a guess"]'::jsonb,0,'Probable cause supports arrest.','original'),
('127.751.d.7.C',4,'An arrest requires that an officer have:','["a rumor", "probable cause or a valid warrant", "a complaint about noise", "a hunch"]'::jsonb,1,'Probable cause or a warrant is required.','original'),
('127.751.d.8.A',3,'A civil paper server studies garnishment and attachment. These are examples of:','["traffic laws", "criminal charges", "civil law procedures", "school policy"]'::jsonb,2,'Civil procedures involve property and claims.','original'),
('127.751.d.8.A',4,'A court order that takes part of a debtor''s wages to pay a debt is called:','["bail", "parole", "probation", "garnishment"]'::jsonb,3,'Garnishment collects debts.','original'),
('127.751.d.8.B',3,'An officer serving civil papers may not break into a home to do so. This identifies:','["limits on force and entry in civil procedures", "criminal arrest rules", "unlimited power", "no limits"]'::jsonb,0,'Civil process has strict limits.','original'),
('127.751.d.8.B',4,'In civil process service, an officer generally may not:','["knock politely", "use force to enter a private home without legal authority", "hand over papers", "record the time"]'::jsonb,1,'Force and entry are restricted.','original'),
('127.751.d.8.C',3,'A class compares a protective order from a family court, a no-contact condition of bond and a restraining order. This differentiates:','["diplomas", "traffic tickets", "types of protective and no-contact orders", "vehicle titles"]'::jsonb,2,'Order types differ in source and scope.','original'),
('127.751.d.8.C',4,'A no-contact order set as a condition of bond usually:','["frees the defendant", "ends the case", "appoints a lawyer", "bars the defendant from contacting the victim"]'::jsonb,3,'Bond conditions can prohibit contact.','original'),
('127.751.d.8.D',3,'A student studies when an officer may take a person in crisis to a hospital for evaluation without a criminal charge. This identifies:','["requirements for emergency mental health evaluation", "jury rules", "traffic rules", "tax rules"]'::jsonb,0,'Emergency detention follows legal criteria.','original'),
('127.751.d.8.D',4,'An officer may detain someone for emergency mental health evaluation if the person:','["is late", "appears mentally ill and presents a substantial risk of harm", "is unpopular", "is just rude"]'::jsonb,1,'Risk of harm is key.','original'),
('127.751.d.9.A',3,'A student studies the Texas Alcoholic Beverage Code on who may sell, serve and consume alcohol. This explains:','["parking laws", "housing law", "alcohol and beverage laws and procedures", "school law"]'::jsonb,2,'The code governs alcohol.','original'),
('127.751.d.9.A',4,'The state agency that regulates alcohol sales in Texas is the:','["Texas Parks Board", "Texas Education Agency", "Texas Lottery Board", "Texas Alcoholic Beverage Commission"]'::jsonb,3,'TABC enforces alcohol law.','original'),
('127.751.d.9.B',3,'The Texas code defines beer, wine and liquor above a set alcohol content. These are:','["alcoholic beverages", "soft drinks", "juices", "teas"]'::jsonb,0,'Definitions set what is regulated.','original'),
('127.751.d.9.B',4,'Under Texas law, an alcoholic beverage includes:','["only water", "beer, wine and distilled spirits", "only milk", "only juice"]'::jsonb,1,'Alcohol covers several types.','original'),
('127.751.d.9.C',3,'A clerk who sells beer to a 17-year-old is making an illegal sale, while one who checks ID and sells to a 25-year-old is making a legal sale. This differentiates:','["jobs", "wages", "legal and illegal alcohol sales", "shifts"]'::jsonb,2,'Age and licensing determine legality.','original'),
('127.751.d.9.C',4,'Selling alcohol to a minor is generally:','["required", "legal", "encouraged", "illegal"]'::jsonb,3,'Sales to minors are prohibited.','original'),
('127.751.d.9.D',3,'An adult drinks a glass of wine at a licensed restaurant. This is a circumstance where alcohol:','["may be legally consumed", "is always illegal", "is a crime", "is banned in all places"]'::jsonb,0,'Legal consumption occurs in permitted settings by adults.','original'),
('127.751.d.9.D',4,'Under Texas law, alcohol may be legally consumed by:','["anyone in a school", "adults of legal drinking age in permitted places", "minors at parties", "drivers on the road"]'::jsonb,1,'Age and place matter.','original'),
('127.751.d.10.A',3,'At the roadside, a student guides a volunteer through the Horizontal Gaze Nystagmus test and the walk-and-turn. These are:','["eye charts", "math quizzes", "standardized field sobriety tests", "fitness drills"]'::jsonb,2,'SFSTs help detect impairment.','original'),
('127.751.d.10.A',4,'The three standardized field sobriety tests are HGN, walk-and-turn and:','["sprint", "jump rope", "swim test", "one-leg stand"]'::jsonb,3,'The third test is the one-leg stand.','original'),
('127.751.d.10.B',3,'A driver weaves, brakes late and drifts across lines. These are:','["indicators of impaired driving", "good driving habits", "normal practices", "signs of skill"]'::jsonb,0,'Erratic driving suggests impairment.','original'),
('127.751.d.10.B',4,'Which is a common indicator of an impaired driver?','["signaling a turn", "driving without headlights at night", "staying in lane", "obeying the speed limit"]'::jsonb,1,'Missing headlights at night is a cue.','original'),
('127.751.d.10.C',3,'Officers use patrol observation, sobriety checkpoints and breath tests to find impaired drivers. These are:','["school methods", "filing methods", "methods to detect and apprehend impaired drivers", "tax methods"]'::jsonb,2,'Detection uses observation and tests.','original'),
('127.751.d.10.C',4,'A device that measures breath alcohol at the roadside is a:','["radar gun", "stop stick", "flashlight", "preliminary breath test device"]'::jsonb,3,'PBTs estimate BAC.','original'),
('127.751.d.10.D',3,'After a DWI arrest, an officer writes a detailed report and gathers video, test results and statements for court. This is:','["preparing evidence and reports for DWI testimony", "skipping paperwork", "guessing", "closing the case"]'::jsonb,0,'Documentation supports testimony.','original'),
('127.751.d.10.D',4,'In a DWI case, the officer''s report should record:','["the officer''s lunch", "observed driving, test results and statements", "the car''s resale value", "opinions about the driver''s character"]'::jsonb,1,'Facts support prosecution.','original'),
('127.751.d.11.A',3,'At a large protest, a supervisor orders pepper spray and bean bag rounds be deployed only under strict policy. This is:','["handing out water", "traffic control", "deployment of less-than-lethal and chemical crowd control", "patrol briefings"]'::jsonb,2,'Crowd control tools are regulated.','original'),
('127.751.d.11.A',4,'Less-than-lethal options are meant to:','["replace training", "avoid reports", "cause maximum harm", "gain compliance with a lower risk of death"]'::jsonb,3,'They reduce the risk of fatality.','original'),
('127.751.d.11.B',3,'Before deploying at an event, commanders assess crowd size, mood, exits and officer safety. This is a:','["needs assessment for crowd management", "parking review", "payroll check", "menu check"]'::jsonb,0,'Assessment guides tactics.','original'),
('127.751.d.11.B',4,'A crowd management assessment should include:','["the price of tickets", "crowd size, mood and available escape routes", "the band''s playlist", "the weather forecast only"]'::jsonb,1,'Conditions affect planning.','original'),
('127.751.d.11.C',3,'Officers set up barricades and lines to keep a march away from a hospital entrance. This is:','["parking", "debating", "establishing perimeters for crowd control", "filming"]'::jsonb,2,'Perimeters control movement.','original'),
('127.751.d.11.C',4,'A perimeter in crowd control helps to:','["block officers", "start a riot", "hide evidence", "contain the area and protect people and property"]'::jsonb,3,'Perimeters limit spread.','original'),
('127.751.d.11.D',3,'An officer spots the organizer who is calming people, the agitators and bystanders needing protection. This shows the need to identify:','["group leaders, followers and victims", "weather", "clothing styles", "music"]'::jsonb,0,'Roles shape response.','original'),
('127.751.d.11.D',4,'Identifying a crowd''s leaders can help officers to:','["avoid talking", "communicate and de-escalate through them", "ignore the crowd", "arrest everyone"]'::jsonb,1,'Leaders can influence crowd behavior.','original'),
('127.751.d.12.A',3,'In a drill, an officer moves from presence and verbal commands to hands-on control as a subject escalates. This demonstrates:','["a map", "a rule of grammar", "the force continuum", "a ledger"]'::jsonb,2,'The continuum matches force to resistance.','original'),
('127.751.d.12.A',4,'Under the force continuum, an officer should use:','["no force ever", "the highest force first", "random force", "only the level of force reasonably needed"]'::jsonb,3,'Force must be proportional.','original'),
('127.751.d.12.B',3,'State and federal courts and legislatures set limits on when officers may use force. These are:','["guidelines and restrictions on force by governments", "jokes", "suggestions", "menu items"]'::jsonb,0,'Government rules limit force.','original'),
('127.751.d.12.B',4,'In Graham v. Connor, the Supreme Court said officers'' force is judged by:','["officer intent", "objective reasonableness", "public opinion", "the outcome only"]'::jsonb,1,'Reasonableness standard.','original'),
('127.751.d.12.C',3,'An officer''s authority to use force comes from statutes such as the Texas Penal Code Chapter 9. This identifies:','["an overtime rule", "a memo", "the legal authority for use of force", "a dress code"]'::jsonb,2,'Law grants limited authority.','original'),
('127.751.d.12.C',4,'Chapter 9 of the Texas Penal Code deals with:','["tax law", "marriage law", "parking law", "justification excluding criminal responsibility, including use of force"]'::jsonb,3,'Chapter 9 sets justification.','original'),
('127.751.d.12.D',3,'After using a baton, an officer must explain why the force was needed and whether it was reasonable. This is:','["evaluating less-than-lethal force", "writing poetry", "hiding facts", "avoiding review"]'::jsonb,0,'Use of force is reviewed.','original'),
('127.751.d.12.D',4,'A less-than-lethal force review asks whether the force was:','["colorful", "reasonable for the threat faced", "popular", "fashionable"]'::jsonb,1,'Reasonableness is the test.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
